125	async function makeClaim(
126	  chainId: number,
127	  epoch: number,
128	  epochPeriod: number,
129	  transactionHandler: ITransactionHandler,
130	  veaInbox: any,
131	  veaOutbox: any,
132	  veaOutboxProvider: JsonRpcProvider,
133	  queryRpc: JsonRpcProvider,
134	  emitter: EventEmitter,
135	  fetchLatestClaimedEpoch: typeof getLastClaimedEpoch = getLastClaimedEpoch,
136	  fetchBlocksAndCheckFinality: typeof getBlocksAndCheckFinality,
137	  fetchSettledReadBlocks: typeof resolveSettledReadBlocks = resolveSettledReadBlocks
138	): Promise<ITransactionHandler | null> {
139	  // Claiming stakes a deposit on the snapshot we are about to read, so resolve
140	  // the settled blocks first and read only at them.
141	  // `queryRpc` is the L1 the inbox's rollup posts batches to (the router on
142	  // arbToGnosis, the outbox itself on arbToEth) and is only valid for that
143	  // Arbitrum->L1 finality math. Every read against `veaOutbox` must instead be
144	  // pinned to a block of the outbox's OWN chain (Chiado on arbToGnosis), whose
145	  // numbering is unrelated to the router's.
146	  const settledBlocks = await fetchSettledReadBlocks({
147	    inboxProvider: transactionHandler.veaInboxProvider,
148	    outboxProvider: queryRpc,
149	    epoch,
150	    epochPeriod,
151	    emitter: emitter as any,
152	    fetchBlocksAndCheckFinality,
153	  });
154	  if (!settledBlocks) return null;
155	
156	  const savedSnapshot = await veaInbox.snapshots(epoch, { blockTag: settledBlocks.inboxBlock });
157	  if (savedSnapshot == ethers.ZeroHash) {
158	    return null;
159	  }
160	  const outboxHeadBlock = await veaOutboxProvider.getBlock("finalized");
161	  const outboxStateRoot = await veaOutbox.stateRoot({ blockTag: outboxHeadBlock.number });
162	  let lastClaimedStateroot: string | null = null;
163	  try {
164	    const floorBlock = await getLookbackFloorBlock({ provider: veaOutboxProvider, chainId, epochPeriod });
165	    const lastClaimLog = await findLatestLog({
166	      contract: veaOutbox,
167	      filter: veaOutbox.filters.Claimed(),
168	      fromBlock: floorBlock,
169	      toBlock: outboxHeadBlock.number,
170	    });
171	    lastClaimedStateroot = lastClaimLog?.data ?? null;
172	  } catch {
173	    const claimData = await fetchLatestClaimedEpoch(veaOutbox.target, chainId);
174	    lastClaimedStateroot = claimData ? claimData.stateRoot : ethers.ZeroHash;
175	  }
176	  if (lastClaimedStateroot == null) {
177	    return null;
178	  }
179	  const newMessagesToBridge = savedSnapshot != outboxStateRoot && savedSnapshot != lastClaimedStateroot;
180	  if (newMessagesToBridge) {
181	    await transactionHandler.makeClaim(savedSnapshot);
182	    return transactionHandler;
183	  }
184	  return null;
185	}
