187	async function verifyClaim(
188	  transactionHandler: ITransactionHandler,
189	  claim: ClaimStruct,
190	  veaOutboxProvider: JsonRpcProvider
191	) {
192	  if (claim.honest == ClaimHonestState.CLAIMER) {
193	    await transactionHandler.withdrawClaimDeposit();
194	    return transactionHandler;
195	  } else if (claim.honest == ClaimHonestState.NONE) {
196	    const finalizedOutboxBlock = await veaOutboxProvider.getBlock("finalized");
197	    if (claim.challenger != ethers.ZeroAddress) {
198	      return transactionHandler;
199	    }
200	    if (claim.timestampVerification == 0) {
201	      await transactionHandler.startVerification(finalizedOutboxBlock.timestamp);
202	    } else {
203	      await transactionHandler.verifySnapshot(finalizedOutboxBlock.timestamp);
204	    }
205	    return transactionHandler;
206	  }
207	}
