3	// DONT DECLARE A NEW var here, i think this wont be needed after we update the lowerbound comment i made below
4	// Extra backlog for the cold-start epoch sweep, so a restart still picks up
5	// claims that were pending L2 finalization when the bot went down.
6	const COLD_START_BACKLOG_SECS = 7 * 24 * 60 * 60;
7	
8	interface EpochRangeParams {
9	  chainId: number;
10	  epochPeriod: number;
11	  currentTimestamp: number;
12	  now?: number;
13	  fetchBridgeConfig?: typeof getBridgeConfig;
14	}
15	
16	/**
17	 * Sets the epoch range to check for claims.
18	 *
19	 * @param currentTimestamp - The current timestamp
20	 * @param chainId - The chain ID
21	 * @param now - The current time in milliseconds (optional, defaults to Date.now())
22	 * @param fetchBridgeConfig - The function to fetch the bridge configuration (optional, defaults to getBridgeConfig)
23	 *
24	 * @returns The epoch range to check for claims
25	 */
26	
27	const setEpochRange = ({
28	  chainId,
29	  currentTimestamp,
30	  epochPeriod,
31	  now = Date.now(),
32	  fetchBridgeConfig = getBridgeConfig,
33	}: EpochRangeParams): Array<number> => {
34	  const { sequencerDelayLimit } = fetchBridgeConfig(chainId);
35	
36	  // When Sequencer is malicious, even when L1 is finalized, L2 state might be unknown for up to  sequencerDelayLimit + epochPeriod.
37	  const L2SyncPeriod = sequencerDelayLimit + epochPeriod;
38	  // When we start the watcher, we need to go back far enough to check for claims which may have been pending L2 state finalization.
39	  const veaEpochOutboxWatchLowerBound =
40	    Math.floor((currentTimestamp - L2SyncPeriod - COLD_START_BACKLOG_SECS) / epochPeriod) - 2;
41	  // ETH / Gnosis POS assumes synchronized clocks
42	  // using local time as a proxy for true "latest" L1 time
43	  const timeLocal = Math.floor(now / 1000);
44	
45	  let veaEpochOutboxClaimableNow = Math.floor(timeLocal / epochPeriod) - 1;
46	  // only past epochs are claimable, hence shift by one here
47	  const length = veaEpochOutboxClaimableNow - veaEpochOutboxWatchLowerBound;
48	  const veaEpochOutboxCheckClaimsRangeArray: number[] = Array.from(
49	    { length },
50	    (_, i) => veaEpochOutboxWatchLowerBound + i + 1
51	  );
52	  return veaEpochOutboxCheckClaimsRangeArray;
53	};
54	
55	const getLatestChallengeableEpoch = (epochPeriod: number, now: number = Date.now()): number => {
56	  return Math.floor(now / 1000 / epochPeriod) - 2;
57	};
58	
59	interface BlockAtTimestampParams {
60	  provider: JsonRpcProvider;
61	  timestamp: number;
62	  floorBlock?: number;
63	  headBlockTag?: "latest" | "finalized";
64	}
65	
66	// Blocks sampled back from the head to observe the chain's recent block rate.
67	const BLOCK_RATE_SAMPLE_SIZE = 1000;
68	// Chains differ by orders of magnitude (Arbitrum ~0.25s, Ethereum ~12s), so the
69	// rate is measured rather than configured. This only guards against divide-by-zero.
70	const MIN_SECONDS_PER_BLOCK = 0.05;
71	
72	/**
73	 * Find the block that contains a given timestamp.
74	 *
75	 * Returns the highest block number whose timestamp is at or before `timestamp`.
76	 *
77	 * Runs in three steps: estimate where the target sits from the chain's recent
78	 * block rate, widen that estimate backwards until it really is behind the
79	 * target, then bisect. The estimate matters because anchoring the search at
80	 * block 0 would cost a pointless round trip to genesis and make the starting
81	 * bracket the entire chain; the widening step is what keeps the result correct
82	 * when the chain's rate has changed and the estimate is therefore wrong.
83	 *
84	 * @returns The block number containing `timestamp`
85	 */
86	const blockAtTimestamp = async ({
87	  provider,
88	  timestamp,
89	  floorBlock = 0,
90	  headBlockTag = "finalized",
91	}: BlockAtTimestampParams): Promise<number> => {
92	  const headBlock = await provider.getBlock(headBlockTag);
93	  if (timestamp >= headBlock.timestamp) return headBlock.number;
94	
95	  const sampleNumber = Math.max(headBlock.number - BLOCK_RATE_SAMPLE_SIZE, floorBlock);
96	  const sampleBlock = await provider.getBlock(sampleNumber);
97	  const secondsPerBlock = Math.max(
98	    (headBlock.timestamp - sampleBlock.timestamp) / Math.max(headBlock.number - sampleNumber, 1),
99	    MIN_SECONDS_PER_BLOCK
100	  );
101	
102	  let span = Math.ceil((headBlock.timestamp - timestamp) / secondsPerBlock);
103	  let low = Math.max(headBlock.number - span, floorBlock);
104	  let lowBlock = await provider.getBlock(low);
105	  while (lowBlock.timestamp > timestamp && low > floorBlock) {
106	    span *= 2;
107	    low = Math.max(headBlock.number - span, floorBlock);
108	    lowBlock = await provider.getBlock(low);
109	  }
110	  if (lowBlock.timestamp > timestamp) return floorBlock;
111	
112	  let high = headBlock.number;
113	  while (high - low > 1) {
114	    const middle = Math.floor((low + high) / 2);
115	    const block = await provider.getBlock(middle);
116	    if (block.timestamp <= timestamp) low = middle;
117	    else high = middle;
118	  }
119	  return low;
120	};
121	
122	interface LookbackFloorParams {
123	  provider: JsonRpcProvider;
124	  chainId: number;
125	  epochPeriod: number;
126	  headBlockTag?: "latest" | "finalized";
127	  fetchBridgeConfig?: typeof getBridgeConfig;
128	}
129	// Logically the loop back should be limited to the sequencerDelayLimit + epochPeriod, but we add a backlog to account for the time it takes for the bot to start up and catch up with the chain. But i think thats too harsh and we should just use the sequencerDelayLimit + epochPeriod as the limit. Maybe 2 epoch periods?
130	/**
131	 * The oldest block worth searching for a "latest event of its kind" lookup.
132	 *
133	 * Bounded by the protocol's worst-case L2 sync window. This is a cheap on-chain
134	 * fast path with an indexer fallback behind it, so it deliberately does not
135	 * carry the cold-start backlog: `findLatestLog` scans backward with early exit,
136	 * meaning a wider floor costs nothing when events are recent and costs the most
137	 * when there are none to find. On Arbitrum the backlog would be ~2.4M blocks of
138	 * empty scanning before falling back to the indexer anyway.
139	 *
140	 * @returns The block number to stop searching backward at
141	 */
142	const getLookbackFloorBlock = async ({
143	  provider,
144	  chainId,
145	  epochPeriod,
146	  headBlockTag = "finalized",
147	  fetchBridgeConfig = getBridgeConfig,
148	}: LookbackFloorParams): Promise<number> => {
149	  const { sequencerDelayLimit } = fetchBridgeConfig(chainId);
150	  const headBlock = await provider.getBlock(headBlockTag);
151	  const floorTimestamp = headBlock.timestamp - (sequencerDelayLimit + epochPeriod);
152	  if (floorTimestamp <= 0) return 0;
153	  return blockAtTimestamp({ provider, timestamp: floorTimestamp, headBlockTag });
154	};
155	
156	/**
157	 * Get the block number corresponding to a given epoch.
158	 *
159	 * @param epoch - The epoch number
160	 * @param epochPeriod - The epoch period in seconds
161	 * @param provider - The JSON-RPC provider
162	 *
163	 * @returns The block number corresponding to the given epoch
164	 */
165	const getBlockFromEpoch = async (epoch: number, epochPeriod: number, provider: JsonRpcProvider): Promise<number> =>
166	  blockAtTimestamp({ provider, timestamp: epoch * epochPeriod });
167	
