it("runs the arbToGnosis finality check against the router's chain, not the outbox's", async () => {
  // The Arbitrum->L1 finality check (findBatchContainingBlock ->
  // SequencerBatchDelivered) is only meaningful against the L1 the rollup
  // posts batches to. On arbToGnosis that L1 is the Sepolia router, NOT
  // the Chiado outbox, so checkAndClaim must resolve
  // `queryRpc = veaRouterProvider ?? veaOutboxProvider` and hand it to
  // resolveSettledReadBlocks as `outboxProvider`. Pointed at Chiado the
  // check throws or flags a finality issue and the bot never claims.
  const ROUTER_HEAD = 7_000_000; // Sepolia scale
  const OUTBOX_HEAD = 30_000_000; // Chiado scale
  const SEC_PER_BLOCK = 5;

  // Distinct objects: the assertions below are on reference identity, so
  // an `undefined` router (the watcher wiring bug) cannot pass by shape.
  const routerProvider: any = {
    chainMarker: "router-sepolia",
    getBlock: jest.fn(async (tag: any) => {
      const number = typeof tag === "number" ? tag : ROUTER_HEAD;
      return { number, timestamp: number * 12 };
    }),
  };
  const outboxProvider: any = {
    chainMarker: "outbox-chiado",
    getBlock: jest.fn(async (tag: any) => {
      const number = typeof tag === "number" ? tag : OUTBOX_HEAD;
      return { number, timestamp: number * SEC_PER_BLOCK };
    }),
  };
  const inboxProvider: any = { chainMarker: "inbox-arbitrum" };

  veaInbox.snapshots = jest.fn().mockResolvedValue("0x7890");
  veaOutbox.stateRoot = jest.fn().mockResolvedValue("0xstateroot");
  veaOutbox.filters = { Claimed: jest.fn(() => ({ event: "Claimed" })) };
  veaOutbox.queryFilter = jest.fn(async () => []);

  // Settled past the epoch boundary ((epoch + 1) * epochPeriod = 110), and
  // with a deliberately Sepolia-scale outbox block the code must not reuse.
  const fetchBlocksAndCheckFinality = jest
    .fn()
    .mockResolvedValue([
      { number: 4242, timestamp: 110 },
      { number: ROUTER_HEAD, timestamp: 110 },
      false,
      false,
    ]);

  mockTransactionHandler.veaInboxProvider = inboxProvider;
  mockDeps.transactionHandler = mockTransactionHandler;
  mockDeps.claim = null;
  mockDeps.veaInbox = veaInbox;
  mockDeps.veaOutbox = veaOutbox;
  mockDeps.veaInboxProvider = inboxProvider;
  mockDeps.veaOutboxProvider = outboxProvider;
  mockDeps.veaRouterProvider = routerProvider;
  mockDeps.chainId = 10200;
  mockDeps.fetchLatestClaimedEpoch = jest.fn().mockResolvedValue({ stateRoot: "0xold" });
  mockDeps.fetchBlocksAndCheckFinality = fetchBlocksAndCheckFinality;
  // The real implementation, so the queryRpc -> resolveSettledReadBlocks ->
  // getBlocksAndCheckFinality wiring is exercised instead of stubbed out.
  mockDeps.fetchSettledReadBlocks = resolveSettledReadBlocks;

  await checkAndClaim(mockDeps);

  expect(fetchBlocksAndCheckFinality).toHaveBeenCalledTimes(1);
  const [finalityL1Provider, finalityL2Provider] = fetchBlocksAndCheckFinality.mock.calls[0];
  expect(finalityL1Provider).toBe(routerProvider);
  expect(finalityL1Provider).not.toBe(outboxProvider);
  expect(finalityL2Provider).toBe(inboxProvider);

  // And the outbox itself is still read at a block of its own chain.
  expect(veaOutbox.stateRoot).toHaveBeenCalledWith({ blockTag: OUTBOX_HEAD });
  expect(veaOutbox.stateRoot).not.toHaveBeenCalledWith({ blockTag: ROUTER_HEAD });
});

